<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserInvitation\Domain\UserInvitationStatusOptions;
use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Accessor\UserInvitationStatusAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserInvitationStatusAccessor trait.
 *
 * Covers null default, string/VO assignment via withStatus,
 * getStatus/status accessors, and isStatusChanged with/without original.
 */
class UserInvitationStatusAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withStatus creates a new instance with the Status set
     * from a string value, and getStatus returns the primitive string.
     */
    public function testWithStatusFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationStatusAccessorUnitTest();

        // Act
        $result = $holder->withStatus(UserInvitationStatusOptions::PENDING);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(UserInvitationStatusOptions::PENDING, $result->getStatus());
    }
    /**
     * Asserts that withstatus has access to the value object
     * from a string value, and getStatus returns the primitive string.
     */
    public function testWithStatusFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationStatusAccessorUnitTest();

        // Act
        $result = $holder->withStatus(UserInvitationStatusOptions::PENDING);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(UserInvitationStatusOptions::PENDING, $result->status()->value());
    }
    public function testChangedStatus(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationStatusAccessorUnitTest();
        $original = $holder->withStatus(UserInvitationStatusOptions::PENDING);
        $same = $holder->withStatus(UserInvitationStatusOptions::PENDING);
        $modified = $holder->withStatus(UserInvitationStatusOptions::ACCEPTED);

        // Act
        $unchanged = $holder->isStatusChanged();
        $withSame = $original->isStatusChanged($same);
        $withDiferent = $original->isStatusChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserInvitationStatusAccessorUnitTest
{
    use UserInvitationStatusAccessor;
}
